'use strict'

const tokenRegExp = /^[!#$%&'*+.^_`|~0-9A-Za-z-]+$/

/**
 * Parses a `content-type` header value into its media type and parameters.
 * Values that do not contain a valid `type/subtype` yield an empty instance.
 */
class ContentType {
  #valid = false
  #empty = true
  #type = ''
  #subtype = ''
  #parameters = new Map()
  #string = ''

  constructor (headerValue) {
    if (headerValue == null || headerValue === '' || headerValue === 'undefined') {
      return
    }
    if (typeof headerValue !== 'string') headerValue = String(headerValue)

    const firstSemi = headerValue.indexOf(';')
    const mediaType = (firstSemi === -1 ? headerValue : headerValue.slice(0, firstSemi)).trim()
    const slash = mediaType.indexOf('/')
    if (slash === -1) return

    const type = mediaType.slice(0, slash)
    const subtype = mediaType.slice(slash + 1)
    if (!tokenRegExp.test(type) || !tokenRegExp.test(subtype)) return

    this.#valid = true
    this.#empty = false
    this.#type = type.toLowerCase()
    this.#subtype = subtype.toLowerCase()
    if (firstSemi !== -1) this.#parseParameters(headerValue, firstSemi + 1)

    let str = this.mediaType
    for (const [name, value] of this.#parameters) {
      str += `; ${name}="${value.replace(/(["\\])/g, '\\$1')}"`
    }
    this.#string = str
  }

  #parseParameters (str, pos) {
    const len = str.length
    while (pos < len) {
      const ch = str[pos]
      if (ch === ';' || ch === ' ' || ch === '\t') {
        pos++
        continue
      }
      let end = pos
      while (end < len && str[end] !== '=' && str[end] !== ';') end++
      const name = str.slice(pos, end).trim().toLowerCase()
      if (end >= len || str[end] === ';') {
        // parameter without a value, skip it
        pos = end
        continue
      }
      pos = end + 1
      let value
      if (str[pos] === '"') {
        pos++
        value = ''
        let closed = false
        while (pos < len) {
          const c = str[pos++]
          if (c === '\\' && pos < len) {
            value += str[pos++]
          } else if (c === '"') {
            closed = true
            break
          } else {
            value += c
          }
        }
        if (!closed) value = 'invalid quoted string'
        // skip anything up to the next parameter
        while (pos < len && str[pos] !== ';') pos++
      } else {
        end = pos
        while (end < len && str[end] !== ';') end++
        value = str.slice(pos, end).trim()
        pos = end
      }
      if (name.length > 0 && !this.#parameters.has(name)) {
        this.#parameters.set(name, value)
      }
    }
  }

  get isEmpty () { return this.#empty }
  get isValid () { return this.#valid }
  get type () { return this.#type }
  get subtype () { return this.#subtype }
  get parameters () { return this.#parameters }
  get mediaType () { return this.#empty ? '' : `${this.#type}/${this.#subtype}` }

  toString () {
    return this.#string
  }
}

